// agent-weather — agent-surface pattern: prop city + action fetchForecast with expose/describe

@state {
  let city = prop({
    default: 'London',
    describe: 'City name to retrieve weather forecast for',
    expose: 'read',
  })

  let forecast = state('')
  let loading = state(false)
  let errorMsg = state('')

  const fetchForecast = action(
    { describe: 'Fetch the latest weather forecast for the current city',
      expose: 'read write' },
    async () => {
        loading = true
        errorMsg = ''
        try {
          const res = await fetch(`/api/weather?city=${encodeURIComponent(city)}`)
          if (!res.ok) throw new Error(`HTTP ${res.status}`)
          forecast = await res.text()
        } catch (e) {
          errorMsg = (e as Error).message
        } finally {
          loading = false
        }
      })
}

@template {
  <div class="weather-agent">
    <h2 class="title">Weather — {city}</h2>
    <group if={loading}>
      <p class="loading">Fetching forecast…</p>
    </group><group elseif={errorMsg}>
      <p class="error">{errorMsg}</p>
    </group><group elseif={forecast}>
      <p class="forecast">{forecast}</p>
    </group><group else>
      <p class="prompt">Press Refresh to load forecast.</p>
    </group>
    <button on:click={fetchForecast} class="refresh-btn" disabled={loading}>
      Refresh
    </button>
  </div>
}

@style {
  .weather-agent { padding: 1.5rem; max-width: 22rem; border: 1px solid var(--border, #ccc); border-radius: 6px; }
  .title { margin: 0 0 1rem; font-size: 1.2rem; }
  .loading { color: var(--info, #036); }
  .error { color: var(--error, #c00); }
  .forecast { font-size: 1rem; line-height: 1.5; }
  .prompt { color: var(--muted, #888); font-style: italic; }
  .refresh-btn { margin-top: 0.75rem; padding: 0.4rem 1rem; cursor: pointer; border: 1px solid var(--border, #ccc); border-radius: 4px; }
  .refresh-btn:disabled { opacity: 0.5; cursor: not-allowed; }
}

// accordion — prop items (array) + action toggle, each over items, show for content

@state {
  const items = prop({
    default: [
        { id: '1', title: 'First item', content: 'Content for the first panel.' },
        { id: '2', title: 'Second item', content: 'Content for the second panel.' },
        { id: '3', title: 'Third item', content: 'Content for the third panel.' },
      ],
  })

  let openId = state('')

  const toggle = action((id: string) => {
      openId = openId === id ? '' : id
    })
}

@template {
  <div class="accordion" role="list">
    <group each={item of items} key={item.id}>
      <div class="accordion-item" role="listitem">
        <button
          class={['accordion-header', openId === item.id && 'open']}
          on:click={() => toggle(item.id)}
          aria-expanded={openId === item.id}
        >
          <span>{item.title}</span>
          <span class="chevron">{openId === item.id ? '▲' : '▼'}</span>
        </button>
        <div show={openId === item.id} class="accordion-body">
          <p>{item.content}</p>
        </div>
      </div>
    </group>
  </div>
}

@style {
  .accordion { border: 1px solid var(--border, #ccc); border-radius: 6px; overflow: hidden; max-width: 32rem; }
  .accordion-item { border-bottom: 1px solid var(--border, #ccc); }
  .accordion-item:last-child { border-bottom: none; }
  .accordion-header { width: 100%; display: flex; justify-content: space-between; align-items: center; padding: 0.75rem 1rem; background: none; border: none; cursor: pointer; font-size: 1rem; text-align: left; }
  .accordion-header.open { background: var(--accent-subtle, #eef); }
  .chevron { font-size: 0.7rem; color: var(--muted, #888); }
  .accordion-body { padding: 0.75rem 1rem; background: var(--panel-bg, #fafafa); }
  .accordion-body p { margin: 0; }
  [hidden] { display: none; }
}

// clock — real-time clock: onMount starts setInterval, onDispose clears it

@state {
  let hours = state('00')
  let minutes = state('00')
  let seconds = state('00')
  let _timerId: number | null = null

  const tick = action(() => {
      const now = new Date()
      hours = String(now.getHours()).padStart(2, '0')
      minutes = String(now.getMinutes()).padStart(2, '0')
      seconds = String(now.getSeconds()).padStart(2, '0')
    })

  onMount(() => {
      tick()
      _timerId = setInterval(() => tick(), 1000) as unknown as number
    })
  onDispose(() => {
      if (_timerId !== null) {
        clearInterval(_timerId)
        _timerId = null
      }
    })
}

@template {
  <div class="clock" role="timer" aria-live="off">
    <span class="digit">{hours}</span>
    <span class="sep">:</span>
    <span class="digit">{minutes}</span>
    <span class="sep">:</span>
    <span class="digit seconds">{seconds}</span>
  </div>
}

@style {
  .clock { display: flex; align-items: center; gap: 0.1rem; font-size: 3rem; font-variant-numeric: tabular-nums; font-family: monospace; padding: 1rem; }
  .digit { background: var(--digit-bg, #111); color: var(--digit-fg, #0f0); padding: 0.1em 0.2em; border-radius: 4px; min-width: 1.5ch; text-align: center; }
  .sep { color: var(--muted, #888); padding: 0 0.05em; }
  .seconds { color: var(--seconds-fg, #0af); }
}

// controller — controller() intrinsic wrapping a ResizeObserver reactive controller

@state {
  let width = state(0)
  let height = state(0)

  const setSize = action((w: number, h: number) => {
    width = w
    height = h
  })

  const resizeObserver = controller({ describe: 'Tracks host size via ResizeObserver' }, () => {
    let observer: ResizeObserver | null = null
    return {
      hostConnected: () => {
        observer = new ResizeObserver((entries) => {
          const rect = entries[0]?.contentRect
          setSize(Math.round(rect?.width ?? 0), Math.round(rect?.height ?? 0))
        })
        observer.observe((ctx.host as ShadowRoot).host)
      },
      hostDisconnected: () => {
        observer?.disconnect()
        observer = null
      },
    }
  })
}

@template {
  <div class="controller-demo">
    <div class="resize-box">
      <p class="dim">Width: <strong>{width}px</strong></p>
      <p class="dim">Height: <strong>{height}px</strong></p>
      <p class="hint">Resize the component to see updates.</p>
    </div>
  </div>
}

@style {
  .controller-demo { padding: 1rem; resize: both; overflow: auto; border: 2px dashed var(--border, #ccc); min-width: 200px; min-height: 100px; }
  .resize-box { display: grid; gap: 0.25rem; }
  .dim { margin: 0; font-family: monospace; font-size: 0.9rem; }
  .hint { margin: 0.5rem 0 0; font-size: 0.8rem; color: var(--muted, #888); }
}

// counter — prop count + action increment/decrement/reset

@state {
  let count = prop({ default: 0 })

  const increment = action(() => { count++ })
  const decrement = action(() => { count-- })
  const reset = action(() => { count = 0 })
}

@template {
  <section class="counter">
    <output class="count">{count}</output>
    <div class="controls">
      <button on:click={decrement} class="btn">−</button>
      <button on:click={reset} class="btn btn-ghost">Reset</button>
      <button on:click={increment} class="btn">+</button>
    </div>
  </section>
}

@style {
  .counter { display: grid; gap: 0.75rem; padding: 1.5rem; max-width: 14rem; }
  .count { font-size: 2.5rem; font-variant-numeric: tabular-nums; text-align: center; display: block; }
  .controls { display: flex; gap: 0.5rem; }
  .btn { flex: 1; padding: 0.5rem; cursor: pointer; border: 1px solid var(--border, #ccc); border-radius: 4px; }
  .btn-ghost { background: transparent; }
}

// modal — prop open, action show/hide, on:keydown for Escape, aria() for aria-modal+role="dialog"

@state {
  let open = prop({ default: false })

  aria({
    role: 'dialog',
    modal: 'true',
    label: 'Modal dialog',
  })

  const show = action(() => { open = true })
  const hide = action(() => { open = false })
  const onKeydown = action((e: KeyboardEvent) => {
      if (e.key === 'Escape') hide()
    })
}

@template {
  <div
    class="modal-root"
    show={open}
    on:keydown={onKeydown}
    tabindex="-1"
  >
    <div class="backdrop" on:click={hide}></div>
    <div class="modal-box" role="document">
      <button class="close-btn" on:click={hide} aria-label="Close dialog">×</button>
      <div class="modal-content">
        <slot />
      </div>
    </div>
  </div>
}

@style {
  .modal-root { position: fixed; inset: 0; z-index: 100; display: flex; align-items: center; justify-content: center; }
  .backdrop { position: absolute; inset: 0; background: rgba(0,0,0,0.5); }
  .modal-box { position: relative; background: var(--surface, #fff); border-radius: 8px; padding: 1.5rem; min-width: 20rem; max-width: 90vw; box-shadow: 0 8px 32px rgba(0,0,0,0.2); }
  .close-btn { position: absolute; top: 0.75rem; right: 0.75rem; background: none; border: none; font-size: 1.5rem; cursor: pointer; line-height: 1; color: var(--muted, #888); }
  .close-btn:hover { color: var(--fg, #111); }
  .modal-content { margin-top: 0.5rem; }
  [hidden] { display: none !important; }
}

// tabs — prop tabs + action selectTab, derived selected (active tab)

@state {
  const tabs = prop({
    default: [
        { id: 'overview', label: 'Overview', content: 'Overview panel content.' },
        { id: 'details', label: 'Details', content: 'Details panel content.' },
        { id: 'settings', label: 'Settings', content: 'Settings panel content.' },
      ],
  })

  let activeId = state('')

  const selected = derived(() => tabs.find(t => t.id === activeId) ?? tabs[0] ?? null)

  onMount(() => {
      if (tabs.length > 0) activeId = tabs[0].id
    })

  const selectTab = action((id: string) => { activeId = id })
}

@template {
  <div class="tabs-component">
    <div class="tab-list" role="tablist">
      <group each={tab of tabs} key={tab.id}>
        <button
          role="tab"
          class={['tab-btn', activeId === tab.id && 'active']}
          aria-selected={activeId === tab.id}
          on:click={() => selectTab(tab.id)}
        >
          {tab.label}
        </button>
      </group>
    </div>
    <div class="tab-panel" role="tabpanel">
      <group if={selected}>
        <p>{selected.content}</p>
      </group><group else>
        <p class="empty">No tab selected.</p>
      </group>
    </div>
  </div>
}

@style {
  .tabs-component { max-width: 32rem; border: 1px solid var(--border, #ccc); border-radius: 6px; overflow: hidden; }
  .tab-list { display: flex; border-bottom: 1px solid var(--border, #ccc); background: var(--tab-bar-bg, #f5f5f5); }
  .tab-btn { flex: 1; padding: 0.6rem 0.75rem; background: none; border: none; border-bottom: 3px solid transparent; cursor: pointer; font-size: 0.9rem; }
  .tab-btn.active { border-bottom-color: var(--accent, #0066cc); color: var(--accent, #0066cc); font-weight: 600; }
  .tab-panel { padding: 1rem; }
  .tab-panel p { margin: 0; }
  .empty { color: var(--muted, #888); font-style: italic; }
}

// toast — prop message + action dismiss, auto-dismiss via onMount setTimeout

@state {
  const message = prop({ default: 'Something happened.' })
  const duration = prop({ default: 3000 })

  let visible = state(false)
  let _timerId: number | null = null

  const dismiss = action(() => {
      visible = false
      if (_timerId !== null) { clearTimeout(_timerId); _timerId = null }
    })

  onMount(() => {
      visible = true
      _timerId = setTimeout(() => { visible = false }, duration) as unknown as number
    })
  onDispose(() => {
      if (_timerId !== null) { clearTimeout(_timerId); _timerId = null }
    })
}

@template {
  <div
    class={['toast', visible && 'toast-visible']}
    role="status"
    aria-live="polite"
    show={visible}
  >
    <span class="toast-msg">{message}</span>
    <button class="toast-close" on:click={dismiss} aria-label="Dismiss">×</button>
  </div>
}

@style {
  .toast { display: flex; align-items: center; gap: 0.75rem; padding: 0.6rem 1rem; background: var(--toast-bg, #333); color: var(--toast-fg, #fff); border-radius: 6px; box-shadow: 0 4px 16px rgba(0,0,0,0.2); min-width: 16rem; max-width: 90vw; }
  .toast-msg { flex: 1; font-size: 0.9rem; }
  .toast-close { background: none; border: none; color: inherit; font-size: 1.2rem; cursor: pointer; opacity: 0.7; line-height: 1; padding: 0; }
  .toast-close:hover { opacity: 1; }
  [hidden] { display: none; }
}

// aria-form — aria() for role/aria-label/aria-describedby, form() with value+validity

@state {
  aria({
    role: 'form',
    label: 'Contact form',
    describedby: 'aria-form-hint',
  })

  let name = state('')
  let email = state('')

  form({
    value: () => JSON.stringify({ name, email }),
    validity: () => ({ valueMissing: !name || !email }),
  })

  const onSubmit = action((e: Event) => {
      e.preventDefault()
      console.log('submitted', { name, email })
    })
}

@template {
  <form on:submit={onSubmit} class="aria-form">
    <p id="aria-form-hint" class="hint">All fields are required.</p>
    <label class="field">
      Name
      <input bind:value={name} placeholder="Your name" required />
    </label>
    <label class="field">
      Email
      <input type="email" bind:value={email} placeholder="you@example.com" required />
    </label>
    <button type="submit" class="submit-btn">Submit</button>
  </form>
}

@style {
  .aria-form { display: grid; gap: 0.75rem; max-width: 24rem; padding: 1.5rem; }
  .hint { font-size: 0.85rem; color: var(--muted, #666); margin: 0; }
  .field { display: flex; flex-direction: column; gap: 0.25rem; font-size: 0.9rem; font-weight: 500; }
  .field input { padding: 0.4rem 0.6rem; border: 1px solid var(--border, #ccc); border-radius: 4px; font-size: 1rem; }
  .submit-btn { padding: 0.5rem 1rem; background: var(--accent, #0066cc); color: white; border: none; border-radius: 4px; cursor: pointer; }
}

// context-consumer — consume(): reads theme from ancestor provider
// Pairs with context-provider.aihu; `theme` is the consumed provided value.

@state {
  const theme = consume<string>('theme')
}

@template {
  <div class={['consumer', theme]}>
    <p class="theme-label">
      Active theme: <strong>{theme}</strong>
    </p>
    <div class={['swatch', theme === 'dark' ? 'swatch-dark' : 'swatch-light']}></div>
  </div>
}

@style {
  .consumer { padding: 1rem; border-radius: 4px; transition: background 0.2s; }
  .consumer.light { background: #fff; color: #111; }
  .consumer.dark { background: #111; color: #f0f0f0; }
  .theme-label { margin: 0 0 0.5rem; font-size: 0.9rem; }
  .swatch { width: 2rem; height: 2rem; border-radius: 50%; border: 2px solid currentColor; }
  .swatch-light { background: #fff; }
  .swatch-dark { background: #111; }
}

// context-provider — provide(): exposes a theme token to descendants
// Pairs with context-consumer.aihu, which consumes 'theme' and renders it.

@state {
  let theme = state('light')

  provide('theme', theme)

  const setTheme = action((t: string) => { theme = t })
}

@template {
  <div class="provider" data-theme="light">
    <div class="controls">
      <span class="label">Providing theme: <strong>{theme}</strong></span>
    </div>
    <div class="slot-area">
      <slot />
    </div>
  </div>
}

@style {
  .provider { padding: 1rem; border: 2px solid var(--border, #ccc); border-radius: 6px; }
  .controls { display: flex; align-items: center; gap: 1rem; margin-bottom: 1rem; }
  .label { font-size: 0.9rem; color: var(--muted, #666); }
  .slot-area { padding-top: 0.5rem; border-top: 1px solid var(--border, #eee); }
}

// data-table — prop rows + action sort(col), derived sortedRows, each with key

@state {
  const rows = prop({
    default: [
        { id: '1', name: 'Alice', role: 'Engineer', score: 92 },
        { id: '2', name: 'Bob', role: 'Designer', score: 78 },
        { id: '3', name: 'Carol', role: 'Manager', score: 85 },
        { id: '4', name: 'Dave', role: 'Engineer', score: 91 },
      ],
  })

  let sortCol = state('name')
  let sortDir = state(1)

  const sortedRows = derived(() => [...rows].sort((a, b) => {
      const av = String(a[sortCol] ?? '')
      const bv = String(b[sortCol] ?? '')
      return av.localeCompare(bv) * sortDir
    }))

  const sort = action((col: string) => {
      if (sortCol === col) {
        sortDir = sortDir === 1 ? -1 : 1
      } else {
        sortCol = col
        sortDir = 1
      }
    })
}

@template {
  <div class="data-table-wrapper">
    <table class="data-table">
      <thead>
        <tr>
          <th on:click={() => sort('name')} class={['col-hdr', sortCol === 'name' && 'sorted']}>Name {sortCol === 'name' ? (sortDir === 1 ? '▲' : '▼') : ''}</th>
          <th on:click={() => sort('role')} class={['col-hdr', sortCol === 'role' && 'sorted']}>Role {sortCol === 'role' ? (sortDir === 1 ? '▲' : '▼') : ''}</th>
          <th on:click={() => sort('score')} class={['col-hdr', sortCol === 'score' && 'sorted']}>Score {sortCol === 'score' ? (sortDir === 1 ? '▲' : '▼') : ''}</th>
        </tr>
      </thead>
      <tbody>
        <tr each={row of sortedRows} key={row.id} class="data-row">
          <td>{row.name}</td>
          <td>{row.role}</td>
          <td class="score">{row.score}</td>
        </tr>
      </tbody>
    </table>
  </div>
}

@style {
  .data-table-wrapper { overflow-x: auto; max-width: 100%; }
  .data-table { width: 100%; border-collapse: collapse; font-size: 0.9rem; }
  .col-hdr { padding: 0.5rem 0.75rem; text-align: left; background: var(--table-hdr, #f5f5f5); border-bottom: 2px solid var(--border, #ccc); cursor: pointer; user-select: none; white-space: nowrap; }
  .col-hdr.sorted { color: var(--accent, #0066cc); }
  .data-row td { padding: 0.4rem 0.75rem; border-bottom: 1px solid var(--border, #eee); }
  .data-row:hover td { background: var(--hover-bg, #fafafa); }
  .score { font-variant-numeric: tabular-nums; font-weight: 600; }
}

// fetch-resource — resource() for async fetch with loading/error/data states

@state {
  const url = prop({ default: '/api/resource' })

  const data = resource(async () => {
      const res = await fetch(url)
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      return res.json()
    })
}

@template {
  <div class="fetch-resource">
    <group if={data.loading}>
      <p class="loading">Loading…</p>
    </group><group elseif={data.error}>
      <p class="error">Error: {data.error.message}</p>
    </group><group else>
      <pre class="result">{JSON.stringify(data.value, null, 2)}</pre>
    </group>
  </div>
}

@style {
  .fetch-resource { font-family: monospace; padding: 1rem; }
  .loading { color: var(--info, #036); }
  .error { color: var(--error, #c00); }
  .result { background: var(--code-bg, #f5f5f5); padding: 1rem; border-radius: 4px; overflow: auto; }
}

// form-validation — form() with value+validity for form-associated custom element

@state {
  let value = state('')
  let touched = state(false)

  form({
    value: () => value,
    validity: () => ({ valueMissing: !value.trim(), tooShort: value.trim().length < 2 }),
  })

  const errorMessage = derived(() => {
      if (!touched) return ''
      if (!value.trim()) return 'This field is required.'
      if (value.trim().length < 2) return 'Must be at least 2 characters.'
      return ''
    })
  const isValid = derived(() => value.trim().length >= 2)

  const onInput = action((e: Event) => {
      value = (e.target as HTMLInputElement).value
      touched = true
    })
  const onBlur = action(() => { touched = true })
}

@template {
  <label class="form-field">
    <span class="field-label">Name <span aria-hidden="true">*</span></span>
    <input
      type="text"
      class={['field-input', touched && !isValid && 'invalid']}
      value={value}
      on:input={onInput}
      on:blur={onBlur}
      required
      minlength="2"
    />
    <group if={errorMessage}>
      <span class="error-msg" role="alert">{errorMessage}</span>
    </group>
    <group if={isValid}>
      <span class="valid-msg">Looks good!</span>
    </group>
  </label>
}

@style {
  .form-field { display: flex; flex-direction: column; gap: 0.3rem; max-width: 20rem; }
  .field-label { font-size: 0.9rem; font-weight: 600; }
  .field-input { padding: 0.5rem; border: 1px solid var(--border, #ccc); border-radius: 4px; font-size: 1rem; }
  .field-input.invalid { border-color: var(--error, #c00); }
  .error-msg { font-size: 0.8rem; color: var(--error, #c00); }
  .valid-msg { font-size: 0.8rem; color: var(--success, #080); }
}

// guard-ui — <guard> scope-gated UI: shows content only when scope 'admin' verified

@state {
  const label: string = 'admin-only content'
}

@template {
  <div class="guard-wrapper">
    <guard scope="admin">
      <section class="admin-panel">
        <h2>Admin Panel</h2>
        <p>This {label} is only visible to users with the "admin" scope.</p>
        <button class="action-btn">Perform admin action</button>
      </section>
    </guard>
    <p class="fallback-note">
      Content outside the guard is always visible.
    </p>
  </div>
}

@style {
  .guard-wrapper { padding: 1rem; }
  .admin-panel { padding: 1rem; background: var(--admin-bg, #fff3cd); border: 1px solid var(--admin-border, #ffc107); border-radius: 4px; margin-bottom: 0.75rem; }
  .admin-panel h2 { margin: 0 0 0.5rem; font-size: 1.1rem; }
  .action-btn { margin-top: 0.5rem; padding: 0.4rem 0.75rem; cursor: pointer; border: 1px solid var(--border, #ccc); border-radius: 4px; }
  .fallback-note { font-size: 0.85rem; color: var(--muted, #666); }
}

// infinite-scroll — prop page + action loadMore, IntersectionObserver via controller()

@state {
  const page = prop({ default: 1 })

  let loading = state(false)
  let items = state<Array<{ id: number; text: string }>>([])

  const loadMore = action(async () => {
    if (loading) return
    loading = true
    await new Promise(resolve => setTimeout(resolve, 400))
    const start = items.length
    items = [
      ...items,
      ...Array.from({ length: 10 }, (_, i) => ({
        id: start + i + 1,
        text: `Item ${start + i + 1}`,
      })),
    ]
    loading = false
  })

  const sentinel = controller(() => {
    let observer: IntersectionObserver | null = null
    return {
      hostConnected: () => {
        const el = (ctx.host as ShadowRoot).querySelector('.scroll-sentinel')
        if (!el) return
        observer = new IntersectionObserver((entries) => {
          if (entries[0]?.isIntersecting && !loading) {
            loadMore()
          }
        }, { threshold: 0.1 })
        observer.observe(el)
      },
      hostDisconnected: () => {
        observer?.disconnect()
        observer = null
      },
    }
  })

  onMount(() => { loadMore() })
}

@template {
  <div class="infinite-scroll">
    <ul class="item-list">
      <group each={item of items} key={item.id}>
        <li class="scroll-item">{item.text}</li>
      </group><group empty>
        <li class="scroll-item empty">Loading initial items…</li>
      </group>
    </ul>
    <group if={loading}>
      <p class="loading-indicator">Loading more…</p>
    </group>
    <div class="scroll-sentinel" aria-hidden="true"></div>
  </div>
}

@style {
  .infinite-scroll { max-width: 24rem; max-height: 400px; overflow-y: auto; border: 1px solid var(--border, #ccc); border-radius: 6px; }
  .item-list { list-style: none; padding: 0; margin: 0; }
  .scroll-item { padding: 0.6rem 0.75rem; border-bottom: 1px solid var(--border, #eee); font-size: 0.9rem; }
  .scroll-item:last-child { border-bottom: none; }
  .scroll-item.empty { color: var(--muted, #888); font-style: italic; }
  .loading-indicator { padding: 0.5rem 0.75rem; font-size: 0.85rem; color: var(--muted, #888); text-align: center; }
  .scroll-sentinel { height: 1px; }
}

// search-debounce — bind:value on input + effect() with 300ms debounce, derived results

@state {
  let query = state('')
  let debouncedQuery = state('')
  let _debounceTimer: number | null = null

  effect(() => {
    if (_debounceTimer !== null) clearTimeout(_debounceTimer)
    _debounceTimer = setTimeout(() => {
      debouncedQuery = query
      _debounceTimer = null
    }, 300) as unknown as number
  })

  const results = derived(() => {
      if (!debouncedQuery.trim()) return []
      const q = debouncedQuery.toLowerCase()
      return [
        'apple', 'apricot', 'banana', 'blueberry', 'cherry',
        'grape', 'kiwi', 'lemon', 'mango', 'orange', 'peach', 'pear',
      ].filter(item => item.includes(q))
    })
}

@template {
  <div class="search-box">
    <label class="search-label">
      Search fruits
      <input
        type="search"
        class="search-input"
        bind:value={query}
        placeholder="Type to search…"
        aria-label="Search fruits"
      />
    </label>
    <group if={query && results.length === 0}>
      <p class="no-results">No results for "<strong>{query}</strong>"</p>
    </group><group elseif={results.length > 0}>
      <ul class="result-list">
        <group each={item of results} key={item}>
          <li class="result-item">{item}</li>
        </group>
      </ul>
    </group>
  </div>
}

@style {
  .search-box { max-width: 22rem; padding: 1rem; }
  .search-label { display: flex; flex-direction: column; gap: 0.4rem; font-size: 0.9rem; font-weight: 500; }
  .search-input { padding: 0.5rem; border: 1px solid var(--border, #ccc); border-radius: 4px; font-size: 1rem; width: 100%; }
  .no-results { color: var(--muted, #888); font-size: 0.9rem; margin-top: 0.5rem; }
  .result-list { list-style: none; padding: 0; margin: 0.5rem 0 0; border: 1px solid var(--border, #ccc); border-radius: 4px; overflow: hidden; }
  .result-item { padding: 0.4rem 0.75rem; border-bottom: 1px solid var(--border, #eee); font-size: 0.9rem; }
  .result-item:last-child { border-bottom: none; }
}

// ssr-hydration — SSR-safe component: onMount hydrates from dataset

@state {
  let greeting = prop({ default: 'Hello' })
  let name = prop({ default: 'World' })

  let hydratedFrom: string = 'client'

  onMount(() => {
      const el = _host as HTMLElement
      if (el.dataset.ssrGreeting) greeting = el.dataset.ssrGreeting
      if (el.dataset.ssrName) name = el.dataset.ssrName
      hydratedFrom = el.dataset.ssrGreeting ? 'server' : 'client'
    })
}

@template {
  <div class="ssr-component">
    <p class="greeting">{greeting}, {name}!</p>
    <p class="hydration-source">
      Hydrated from: <code>{hydratedFrom}</code>
    </p>
  </div>
}

@style {
  .ssr-component { padding: 1rem; border: 1px solid var(--border, #ccc); border-radius: 4px; max-width: 24rem; }
  .greeting { font-size: 1.2rem; margin: 0 0 0.5rem; }
  .hydration-source { font-size: 0.8rem; color: var(--muted, #666); margin: 0; }
  code { background: var(--code-bg, #f5f5f5); padding: 0.1em 0.4em; border-radius: 3px; }
}

// tailwind-style — Tailwind 4 utility classes in template + scoped @style for component rules

@state {
  let active = state(false)
  let count = state(0)

  const toggle = action(() => { active = !active })
  const increment = action(() => { count++ })
}

@template {
